SET @prov_c := '%s';
SET	@id := '%s';
SET @cat_id := '%s';
SET	@send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET	@b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_kpi_bmi(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) NOT NULL,
  date_com varchar(14) NOT NULL,
  b_year varchar(4) NOT NULL,
  target int(9) DEFAULT 0,
	result int(9) DEFAULT 0,
	result1 int(9) DEFAULT 0,
	result3 int(9) DEFAULT 0,
	result4 int(9) DEFAULT 0,	
	result5 int(9) DEFAULT 0,	
PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

CALL AddCol('hdc','s_kpi_bmi','result1','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_kpi_bmi','result3','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_kpi_bmi','result4','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_kpi_bmi','result5','int(9) DEFAULT 0 ');

DELETE FROM s_kpi_bmi WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_kpi_bmi
(
SELECT
	 @id,h.hoscode hospcode,concat(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) as areacode
   ,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT CONCAT(t.HOSPCODE,'-',t.PID)) target
,COUNT(DISTINCT IF(t.BMI <18.5 ,CONCAT(t.HOSPCODE,'-',t.PID) ,NULL)) result1
,COUNT(DISTINCT IF(t.BMI >=18.5 AND t.BMI <23.0,CONCAT(t.HOSPCODE,'-',t.PID) ,NULL)) result2
,COUNT(DISTINCT IF(t.BMI >=23.0 AND t.BMI <25.0 ,CONCAT(t.HOSPCODE,'-',t.PID) ,NULL)) result3
,COUNT(DISTINCT IF(t.BMI >=25.0 AND t.BMI <30.0 ,CONCAT(t.HOSPCODE,'-',t.PID) ,NULL)) result4
,COUNT(DISTINCT IF(t.BMI >=30.0 AND t.BMI <150.0 ,CONCAT(t.HOSPCODE,'-',t.PID) ,NULL)) result5
FROM t_person_db p 
	INNER JOIN chospital h on p.check_hosp=h.hoscode 
	INNER JOIN t_screen_lasty t ON p.HOSPCODE=t.HOSPCODE AND p.pid=t.pid  
WHERE  p.NATION in(99) AND p.discharge IN(9)  
			AND TIMESTAMPDIFF(YEAR,p.BIRTH,t.DATE_SERV) BETWEEN 30 AND 44
			AND t.DATE_SERV BETWEEN @start_d AND @end_d AND t.bmi > 0 AND t.BMI <150.0
GROUP BY h.hoscode
);
